import React from "react";
import { Link } from "react-router-dom";
import heroImage from "../images/hero.jpg";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #e6faff, #fff9e6)",
        padding: "60px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION WITH IMAGE */}
      <div
        style={{
          maxWidth: "1000px",
          margin: "auto",
          padding: "160px 40px",
          borderRadius: "40px",
          textAlign: "center",
          backgroundImage: `url(${heroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat",
          boxShadow: "0 30px 60px rgba(0,0,0,0.12)",
          position: "relative",
          overflow: "hidden",
        }}
      >
        {/* Light Overlay */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "rgba(255,255,255,0.6)",
          }}
        ></div>

        <div style={{ position: "relative", zIndex: 2 }}>
          <h1
            style={{
              fontSize: "52px",
              color: "#d63384",
              marginBottom: "20px",
              fontWeight: "700",
            }}
          >
            Nanhe Farishte <br /> Kiran Knits
          </h1>

          <p
            style={{
              fontSize: "20px",
              color: "#444",
              marginBottom: "40px",
            }}
          >
            Har bunai mein maa ka pyaar 💖
          </p>

          <Link to="/products">
            <button
              style={{
                background: "linear-gradient(135deg, #ff4f87, #ff85a2)",
                border: "none",
                padding: "16px 45px",
                borderRadius: "50px",
                color: "white",
                fontSize: "18px",
                fontWeight: "600",
                cursor: "pointer",
                boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
              }}
            >
              🛍 Shop Now
            </button>
          </Link>
        </div>
      </div>

      {/* CATEGORY SECTION (Same as before) */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "34px",
            marginBottom: "60px",
            color: "#444",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform =
            "translateY(-15px) scale(1.05)";
          e.currentTarget.style.background =
            "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform =
            "translateY(0) scale(1)";
          e.currentTarget.style.background = "white";
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
